SELECT   c.fullname AS "Nome do Curso",   COUNT(DISTINCT ue.userid) AS "Total de Inscritos",   COUNT(     DISTINCT CASE       WHEN l.ultimo_acesso IS NOT NULL            AND FROM_UNIXTIME(l.ultimo_acesso) < DATE_SUB(NOW(), INTERVAL 20 DAY)       THEN ue.userid     END   ) AS "Total de Desistentes",   ROUND(     COUNT(       DISTINCT CASE         WHEN l.ultimo_acesso IS NOT NULL              AND FROM_UNIXTIME(l.ultimo_acesso) < DATE_SUB(NOW(), INTERVAL 20 DAY)         THEN ue.userid       END     ) * 100.0 / NULLIF(COUNT(DISTINCT ue.userid), 0),     2   ) AS "Percentual de Desistência (%)" FROM   mdl_course c   JOIN mdl_enrol e ON e.courseid = c.id   JOIN mdl_user_enrolments ue ON ue.enrolid = e.id   JOIN mdl_user u ON u.id = ue.userid   LEFT JOIN (     SELECT       userid,       courseid,       MAX(timecreated) AS ultimo_acesso     FROM       mdl_logstore_standard_log     GROUP BY       userid,       courseid   ) l ON l.userid = ue.userid      AND l.courseid = c.id WHERE   u.deleted = 0   AND ue.status = 0 GROUP BY   c.id,   c.fullname ORDER BY   "Percentual de Desistência (%)" DESC;
